{-# LANGUAGE OverloadedStrings #-}
module Main where

import Network.Wai (Application)
import Network.Wai.Middleware.Static (staticPolicy, addBase)
import Network.Wai.Middleware.RequestLogger (logStdoutDev)
import Network.Wai.Extra.StaticFile (staticApp)
import Web.Scotty (scotty, middleware, get, post, json, text, param, file)
import Network.HTTP.Conduit (simpleHttp)
import Data.Text.Lazy (Text, pack)
import Data.ByteString.Lazy.Char8 (ByteString)
import Data.Aeson (eitherDecode, FromJSON, ToJSON, decode, encode, object, (.=))
import Data.Time (getCurrentTime, utctDay)
import Control.Monad.IO.Class (liftIO)

main :: IO ()
main = do
    scotty 3000 $ do
        middleware logStdoutDev
        middleware $ staticPolicy (addBase "static")
        get "/" $ do
            currentTime <- liftIO getCurrentTime
            text $ pack ("Üdvözlünk! Az aktuális dátum: " ++ show (utctDay currentTime))
        post "/json" $ do
            b <- Web.Scotty.body
            case eitherDecode b of
                Left err -> text $ pack ("JSON hiba: " ++ err)
                Right (v :: Value) -> json v
        get "/http" $ do
            url <- param "url"
            r <- liftIO $ simpleHttp url
            text $ pack (take 500 (show r))
        get "/file/:name" $ do
            name <- param "name"
            file ("static/" ++ name)
